1	package events
2	
3	import (
4		"database/sql"
5		"encoding/json"
6		"errors"
7		"sync"
8	
9		"github.com/alicegogogogogo/local-first-sync-service/internal/store"
10	)
11	
12	// Gate is the only seam the change event service uses to reach the
13	// registration and permission layers. It is evaluated inside the caller's
14	// serialized transaction, so a rejected request never observes change
15	// content and the gate and the gated write commit as one judgment.
16	type Gate interface {
17		// DeviceAuthorizedTx returns nil when deviceID is registered and currently
18		// authorized for documentID, store.ErrDeviceNotFound when the device is not
19		// registered and ErrPermissionDenied when its access was revoked.
20		DeviceAuthorizedTx(tx *sql.Tx, documentID, deviceID string) error
21	}
22	
23	// Service is the change event service: the durable change log, snapshots and
24	// restores plus the in-memory long-poll and subscription observers of them.
25	type Service struct {
26		db   *sql.DB
27		gate Gate
28	
29		// mu guards waits, subs, nextWaitID, nextSubID and closed. Parked long
30		// polls wait on a per-document set of channels; a committed change closes
31		// (signals) every channel parked on it. WebSocket subscriptions live in a
32		// second registry keyed by (document, device): a commit signals every
33		// subscription under the document, while the permission service signals
34		// only the matching device's subscriptions.
35		mu       sync.Mutex
36		waits    map[string]map[uint64]chan struct{}
37		subs     map[subKey]map[uint64]*subscription
38		nextWait uint64
39		nextSub  uint64
40		subWG    sync.WaitGroup
41		closed   bool
42	}
43	
44	// New constructs the change event service over the shared kernel handle and
45	// creates its tables. gate answers the registration/permission checks inside
46	// a write transaction; it may be nil for callers that only use the paths that
47	// do not gate (ordinary post, merge, snapshots, reads).
48	func New(kernel *store.Store, gate Gate) (*Service, error) {
49		db := kernel.DB()
50		if _, err := db.Exec(schema); err != nil {
51			return nil, err
52		}
53		return &Service{
54			db:    db,
55			gate:  gate,
56			waits: make(map[string]map[uint64]chan struct{}),
57			subs:  make(map[subKey]map[uint64]*subscription),
58		}, nil
59	}
60	
61	// PostChanges validates and commits one batch atomically.
62	//
63	// Every change must have a non-empty id; duplicate ids within the batch are
64	// rejected by the caller before reaching this point. On conflict the returned
65	// error is *ErrConflict and nothing is written. Cursors are assigned in batch
66	// order to ids that do not yet exist. Results are returned in the same order
67	// as the input.
68	func (s *Service) PostChanges(documentID string, changes []Change) ([]Result, error) {
69		tx, err := s.db.Begin()
70		if err != nil {
71			return nil, err
72		}
73		defer func() { _ = tx.Rollback() }()
74	
75		results, pending, err := resolveChanges(tx, documentID, changes)
76		if err != nil {
77			return nil, err
78		}
79		if err := appendPending(tx, documentID, changes, pending, results); err != nil {
80			return nil, err
81		}
82	
83		if err := tx.Commit(); err != nil {
84			return nil, err
85		}
86		if len(pending) > 0 {
87			s.notifyWaiters(documentID)
88		}
89		return results, nil
90	}
91	
92	// ReplayChanges commits a retried offline batch with exactly the same change
93	// semantics as PostChanges. It is the document-level replay entry of
94	// CommitAuthorized: the device id travels in the request body there.
95	func (s *Service) ReplayChanges(documentID string, changes []Change) ([]Result, error) {
96		return s.CommitAuthorized(documentID, changes)
97	}
98	
99	// CommitAuthorized validates and commits one batch atomically with exactly the
100	// same change semantics as PostChanges, but enforces the gate (registration
101	// then permission) first in the same transaction: an unregistered device
102	// yields store.ErrDeviceNotFound and a revoked device yields
103	// ErrPermissionDenied. None of those outcomes writes anything or exposes
104	// change content. It is shared by the offline replay and the session-scoped
105	// commit, whose device identity is resolved from the session before the
106	// call.
107	func (s *Service) CommitAuthorized(documentID string, changes []Change) ([]Result, error) {
108		tx, err := s.db.Begin()
109		if err != nil {
110			return nil, err
111		}
112		defer func() { _ = tx.Rollback() }()
113	
114		// Gate first: the device row and the permission row are read before any
115		// change id is resolved, so a rejected replay cannot reveal content.
116		if s.gate != nil {
117			if err := s.gate.DeviceAuthorizedTx(tx, documentID, changes[0].DeviceID); err != nil {
118				return nil, err
119			}
120		}
121	
122		results, pending, err := resolveChanges(tx, documentID, changes)
123		if err != nil {
124			return nil, err
125		}
126		if err := appendPending(tx, documentID, changes, pending, results); err != nil {
127			return nil, err
128		}
129	
130		if err := tx.Commit(); err != nil {
131			return nil, err
132		}
133		if len(pending) > 0 {
134			s.notifyWaiters(documentID)
135		}
136		return results, nil
137	}
138	
139	// resolveChanges resolves every change id against existing rows inside tx,
140	// falling back to the retained summaries of compacted-away ids. A single
141	// device/payload mismatch aborts the whole batch before any cursor is
142	// allocated. It returns the per-id results and the indices of genuinely new
143	// changes that still need a cursor.
144	func resolveChanges(tx *sql.Tx, documentID string, changes []Change) ([]Result, []int, error) {
145		results := make([]Result, len(changes))
146		pending := make([]int, 0, len(changes))
147		for i, c := range changes {
148			var existingDevice string
149			var existingPayload []byte
150			var existingCursor int64
151			err := tx.QueryRow(
152				`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
153				documentID, c.ID,
154			).Scan(&existingCursor, &existingDevice, &existingPayload)
155			switch {
156			case errors.Is(err, sql.ErrNoRows):
157				// No online row: the id may belong to a change compaction
158				// trimmed, whose retained summary still decides idempotency.
159				found, cursor, err := resolveTrimmedIdentity(tx, documentID, c)
160				if err != nil {
161					return nil, nil, err
162				}
163				if !found {
164					pending = append(pending, i)
165					continue
166				}
167				results[i] = Result{
168					ID:      c.ID,
169					Created: false,
170					Cursor:  cursor,
171				}
172			case err != nil:
173				return nil, nil, err
174			default:
175				if existingDevice != c.DeviceID || !store.JSONEqual(existingPayload, c.Payload) {
176					return nil, nil, &ErrConflict{ID: c.ID}
177				}
178				results[i] = Result{
179					ID:      c.ID,
180					Created: false,
181					Cursor:  existingCursor,
182				}
183			}
184		}
185		return results, pending, nil
186	}
187	
188	// appendPending allocates contiguous cursors to the new change indices and
189	// inserts them in input order. It runs inside the caller's transaction. The
190	// allocation continues past the compaction boundary, so trimming the online
191	// log never makes the cursor space restart.
192	func appendPending(tx *sql.Tx, documentID string, changes []Change, pending []int, results []Result) error {
193		nextCursor, err := currentCursorTx(tx, documentID)
194		if err != nil {
195			return err
196		}
197		nextCursor++
198		for _, i := range pending {
199			c := changes[i]
200			if _, err := tx.Exec(
201				`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
202				documentID, nextCursor, c.ID, c.DeviceID, []byte(c.Payload),
203			); err != nil {
204				return err
205			}
206			results[i] = Result{
207				ID:      c.ID,
208				Created: true,
209				Cursor:  nextCursor,
210			}
211			nextCursor++
212		}
213		return nil
214	}
215	
216	// MergeChangeAuthorized is the session-scoped merge: it has exactly the merge
217	// semantics of MergeChange, but enforces the gate (registration then
218	// permission) first in the same serialized transaction: an unregistered device
219	// yields store.ErrDeviceNotFound and a revoked device yields
220	// ErrPermissionDenied. None of those outcomes writes anything or exposes
221	// change content. The device identity is resolved from the session by the HTTP
222	// layer before the call.
223	func (s *Service) MergeChangeAuthorized(documentID string, baseCursor int64, c Change) (MergeResult, error) {
224		tx, err := s.db.Begin()
225		if err != nil {
226			return MergeResult{}, err
227		}
228		defer func() { _ = tx.Rollback() }()
229	
230		// Gate first: the device row and the permission row are read before any
231		// change content is observed, so a rejected merge cannot reveal anything.
232		if s.gate != nil {
233			if err := s.gate.DeviceAuthorizedTx(tx, documentID, c.DeviceID); err != nil {
234				return MergeResult{}, err
235			}
236		}
237	
238		result, appended, err := mergeChangeTx(tx, documentID, baseCursor, c)
239		if err != nil {
240			return MergeResult{}, err
241		}
242		if err := tx.Commit(); err != nil {
243			return MergeResult{}, err
244		}
245		if appended {
246			s.notifyWaiters(documentID)
247		}
248		return result, nil
249	}
250	
251	// MergeChange validates and appends one change against a caller-observed base
252	// cursor, all within a single serialized transaction.
253	//
254	//   - An existing id is idempotent only when deviceId and the decoded payload
255	//     match (Outcome "idempotent", with the original Result); a mismatch is an
256	//     *ErrConflict and nothing is written.
257	//   - A new id with baseCursor equal to the current cursor is appended as
258	//     "applied".
259	//   - A new id with a base cursor behind the current one is appended as
260	//     "merged" only when every change after baseCursor carries a JSON object
261	//     payload whose top-level keys are disjoint from the new payload's; any
262	//     non-object later payload or shared key is an *ErrConflict.
263	//
264	// A non-zero baseCursor for an unknown document, or a baseCursor greater than
265	// the current cursor, returns ErrStaleCursor. A baseCursor below the
266	// compaction boundary returns ErrCompactedBase: the changes the merge would be
267	// checked against have left the online log, so the conflict check cannot be
268	// completed. An unknown document with baseCursor 0 accepts the first change as
269	// "applied".
270	func (s *Service) MergeChange(documentID string, baseCursor int64, c Change) (MergeResult, error) {
271		tx, err := s.db.Begin()
272		if err != nil {
273			return MergeResult{}, err
274		}
275		defer func() { _ = tx.Rollback() }()
276	
277		result, appended, err := mergeChangeTx(tx, documentID, baseCursor, c)
278		if err != nil {
279			return MergeResult{}, err
280		}
281		if err := tx.Commit(); err != nil {
282			return MergeResult{}, err
283		}
284		if appended {
285			s.notifyWaiters(documentID)
286		}
287		return result, nil
288	}
289	
290	// mergeChangeTx runs the merge judgment and (when allowed) the single append
291	// inside the caller's serialized transaction. It reports appended=true only
292	// when a new change row was inserted, so the caller wakes the push channels
293	// exactly once for a change-bearing commit; an idempotent re-post appends
294	// nothing and notifies nothing.
295	func mergeChangeTx(tx *sql.Tx, documentID string, baseCursor int64, c Change) (MergeResult, bool, error) {
296		// Current cursor is the document's high-water mark (0 when unknown); it
297		// never drops below the compaction boundary.
298		current, err := currentCursorTx(tx, documentID)
299		if err != nil {
300			return MergeResult{}, false, err
301		}
302		if baseCursor > current || (baseCursor != 0 && current == 0) {
303			return MergeResult{}, false, ErrStaleCursor
304		}
305		boundary, err := boundaryOfTx(tx, documentID)
306		if err != nil {
307			return MergeResult{}, false, err
308		}
309		if baseCursor < boundary {
310			return MergeResult{}, false, ErrCompactedBase
311		}
312	
313		// An existing id keeps the original idempotency/conflict rules.
314		var existingDevice string
315		var existingPayload []byte
316		var existingCursor int64
317		err = tx.QueryRow(
318			`SELECT cursor, device_id, payload FROM changes WHERE document_id = ? AND id = ?`,
319			documentID, c.ID,
320		).Scan(&existingCursor, &existingDevice, &existingPayload)
321		switch {
322		case errors.Is(err, sql.ErrNoRows):
323			// No online row: a compacted-away id still answers from its retained
324			// summary; anything else is a new id and falls through to the append
325			// logic below.
326			found, cursor, err := resolveTrimmedIdentity(tx, documentID, c)
327			if err != nil {
328				return MergeResult{}, false, err
329			}
330			if found {
331				return MergeResult{
332					ID:      c.ID,
333					Outcome: "idempotent",
334					Cursor:  cursor,
335					Result: &Result{
336						ID:      c.ID,
337						Created: false,
338						Cursor:  cursor,
339					},
340				}, false, nil
341			}
342		case err != nil:
343			return MergeResult{}, false, err
344		default:
345			if existingDevice != c.DeviceID || !store.JSONEqual(existingPayload, c.Payload) {
346				return MergeResult{}, false, &ErrConflict{ID: c.ID}
347			}
348			return MergeResult{
349				ID:      c.ID,
350				Outcome: "idempotent",
351				Cursor:  existingCursor,
352				Result: &Result{
353					ID:      c.ID,
354					Created: false,
355					Cursor:  existingCursor,
356				},
357			}, false, nil
358		}
359	
360		outcome := "applied"
361		if baseCursor < current {
362			// Merge is allowed only when every change after baseCursor is a JSON
363			// object whose top-level keys do not collide with the new payload's.
364			newKeys, err := objectKeys(c.Payload)
365			if err != nil {
366				if errors.Is(err, errNotObject) {
367					return MergeResult{}, false, &ErrConflict{ID: c.ID}
368				}
369				return MergeResult{}, false, err
370			}
371			rows, err := tx.Query(
372				`SELECT payload FROM changes
373				 WHERE document_id = ? AND cursor > ?
374				 ORDER BY cursor ASC`,
375				documentID, baseCursor,
376			)
377			if err != nil {
378				return MergeResult{}, false, err
379			}
380			for rows.Next() {
381				var laterPayload []byte
382				if err := rows.Scan(&laterPayload); err != nil {
383					_ = rows.Close()
384					return MergeResult{}, false, err
385				}
386				laterKeys, err := objectKeys(laterPayload)
387				if err != nil {
388					_ = rows.Close()
389					if errors.Is(err, errNotObject) {
390						return MergeResult{}, false, &ErrConflict{ID: c.ID}
391					}
392					return MergeResult{}, false, err
393				}
394				for k := range newKeys {
395					if _, clash := laterKeys[k]; clash {
396						_ = rows.Close()
397						return MergeResult{}, false, &ErrConflict{ID: c.ID}
398					}
399				}
400			}
401			if err := rows.Err(); err != nil {
402				_ = rows.Close()
403				return MergeResult{}, false, err
404			}
405			_ = rows.Close()
406			outcome = "merged"
407		}
408	
409		next := current + 1
410		if _, err := tx.Exec(
411			`INSERT INTO changes (document_id, cursor, id, device_id, payload) VALUES (?, ?, ?, ?, ?)`,
412			documentID, next, c.ID, c.DeviceID, []byte(c.Payload),
413		); err != nil {
414			return MergeResult{}, false, err
415		}
416		return MergeResult{ID: c.ID, Outcome: outcome, Cursor: next}, true, nil
417	}
418	
419	// errNotObject marks a payload that is not a JSON object.
420	var errNotObject = errors.New("payload is not a JSON object")
421	
422	// objectKeys returns the top-level keys of a JSON object payload. A null,
423	// array or scalar payload yields errNotObject.
424	func objectKeys(raw json.RawMessage) (map[string]struct{}, error) {
425		var m map[string]json.RawMessage
426		if err := json.Unmarshal(raw, &m); err != nil {
427			// Valid JSON that is not an object (array, scalar, null) decodes with
428			// a type error into a map; treat it and malformed JSON as non-object.
429			return nil, errNotObject
430		}
431		if m == nil {
432			return nil, errNotObject
433		}
434		keys := make(map[string]struct{}, len(m))
435		for k := range m {
436			keys[k] = struct{}{}
437		}
438		return keys, nil
439	}
