130	// limit/offset page the fixed order without repeats or gaps; defaults and the
131	// 1..1000 bounds behave like the attachment listing.
132	func TestListSessionsPagination(t *testing.T) {
133		h, _ := newTestHandler(t)
134		registerDevice(t, h, "dev")
135		createSessions(t, h, "dev", "s0", "s1", "s2", "s3", "s4")
136	
