package server

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"testing"

	"github.com/alicegogogogogo/local-first-sync-service/internal/app"
)

// listSessions GETs the device session collection and decodes the sessions
// array plus the count when the status is 200.
func listSessions(t *testing.T, h http.Handler, url string) (*httptest.ResponseRecorder, []string, int) {
	t.Helper()
	r := httptest.NewRequest(http.MethodGet, url, nil)
	w := serveRecorder(h, r)
	if w.Code != http.StatusOK {
		return w, nil, 0
	}
	var body struct {
		Sessions []struct {
			SessionID string `json:"sessionId"`
		} `json:"sessions"`
		Count int `json:"count"`
	}
	if err := json.Unmarshal(w.Body.Bytes(), &body); err != nil {
		t.Fatalf("list body is not JSON: %v body=%s", err, w.Body.String())
	}
	ids := make([]string, 0, len(body.Sessions))
	for _, e := range body.Sessions {
		ids = append(ids, e.SessionID)
	}
	return w, ids, body.Count
}

// createSessions is a small helper that creates one session per id.
func createSessions(t *testing.T, h http.Handler, device string, ids ...string) {
	t.Helper()
	for _, id := range ids {
		w, _ := postJSON(t, h, "/v1/devices/"+device+"/sessions", map[string]any{"sessionId": id})
		if w.Code != http.StatusOK {
			t.Fatalf("create session %q = %d %s", id, w.Code, w.Body.String())
		}
	}
}

// A registered device's sessions are listed, each once, sorted by id,
// regardless of creation order; other devices' sessions never appear.
func TestListSessionsContract(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")
	createSessions(t, h, "dev-1", "sess-c", "sess-a", "sess-b", "sess-a2")
	createSessions(t, h, "dev-2", "sess-foreign")

	w, ids, count := listSessions(t, h, "/v1/devices/dev-1/sessions")
	if w.Code != http.StatusOK {
		t.Fatalf("status = %d body=%s", w.Code, w.Body.String())
	}
	want := []string{"sess-a", "sess-a2", "sess-b", "sess-c"}
	if !equalStrings(ids, want) {
		t.Fatalf("order = %v, want %v", ids, want)
	}
	if count != len(ids) {
		t.Fatalf("count = %d, want %d", count, len(ids))
	}

	// Each item carries only the sessionId key.
	var body struct {
		Sessions []map[string]json.RawMessage `json:"sessions"`
	}
	if err := json.Unmarshal(w.Body.Bytes(), &body); err != nil {
		t.Fatal(err)
	}
	for _, item := range body.Sessions {
		if len(item) != 1 {
			t.Fatalf("item %v must have exactly one key", item)
		}
		if _, ok := item["sessionId"]; !ok {
			t.Fatalf("item %v must carry sessionId", item)
		}
	}

	// The other device sees only its own session.
	_, ids, _ = listSessions(t, h, "/v1/devices/dev-2/sessions")
	if !equalStrings(ids, []string{"sess-foreign"}) {
		t.Fatalf("dev-2 list = %v", ids)
	}

	// A registered device with no sessions gets an empty array and zero.
	registerDevice(t, h, "dev-3")
	w, ids, count = listSessions(t, h, "/v1/devices/dev-3/sessions")
	if w.Code != http.StatusOK || len(ids) != 0 || count != 0 {
		t.Fatalf("empty list = %d %v count=%d", w.Code, ids, count)
	}
	if w.Body.String() != `{"sessions":[],"count":0}`+"\n" {
		t.Fatalf("empty body = %q, want the fixed compact line", w.Body.String())
	}
}

// Byte-level shape: one compact JSON line plus a trailing newline, top-level
// keys in the sessions-then-count order.
func TestListSessionsBodyShape(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev")
	createSessions(t, h, "dev", "s1", "s2")

	r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev/sessions", nil)
	w := serveRecorder(h, r)
	body := w.Body.String()
	if ct := w.Header().Get("Content-Type"); ct != "application/json" {
		t.Fatalf("content-type = %q", ct)
	}
	if !strings.HasSuffix(body, "\n") || strings.Count(body, "\n") != 1 {
		t.Fatalf("body must be one line plus a trailing newline: %q", body)
	}
	if strings.Contains(body, ", ") || strings.Contains(body, ": ") {
		t.Fatalf("body must be compact JSON: %q", body)
	}
	want := `{"sessions":[{"sessionId":"s1"},{"sessionId":"s2"}],"count":2}` + "\n"
	if body != want {
		t.Fatalf("body = %q, want %q", body, want)
	}
}

// limit/offset page the fixed order without repeats or gaps; defaults and the
// 1..1000 bounds behave like the attachment listing.
func TestListSessionsPagination(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev")
	createSessions(t, h, "dev", "s0", "s1", "s2", "s3", "s4")

	// Default limit is 100: one page holds everything in id order.
	_, ids, _ := listSessions(t, h, "/v1/devices/dev/sessions")
	if !equalStrings(ids, []string{"s0", "s1", "s2", "s3", "s4"}) {
		t.Fatalf("default page = %v", ids)
	}

	// Walk the list in pages of two: no duplicates, no gaps.
	var seen []string
	for offset := 0; offset < 5; offset += 2 {
		_, page, count := listSessions(t, h, fmt.Sprintf("/v1/devices/dev/sessions?limit=2&offset=%d", offset))
		if count != len(page) {
			t.Fatalf("page at offset %d count = %d, len = %d", offset, count, len(page))
		}
		seen = append(seen, page...)
	}
	if !equalStrings(seen, []string{"s0", "s1", "s2", "s3", "s4"}) {
		t.Fatalf("paged walk = %v", seen)
	}

	// Partial last page and a page past the end.
	_, page, _ := listSessions(t, h, "/v1/devices/dev/sessions?limit=4&offset=3")
	if !equalStrings(page, []string{"s3", "s4"}) {
		t.Fatalf("last partial page = %v", page)
	}
	w, page, count := listSessions(t, h, "/v1/devices/dev/sessions?offset=5")
	if w.Code != http.StatusOK || len(page) != 0 || count != 0 {
		t.Fatalf("page past end = %d %v count=%d", w.Code, page, count)
	}

	// The accepted bounds.
	for _, query := range []string{"limit=1", "limit=1000", "offset=0"} {
		r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev/sessions?"+query, nil)
		if rec := serveRecorder(h, r); rec.Code != http.StatusOK {
			t.Fatalf("?%s = %d", query, rec.Code)
		}
	}
}

// Illegal pagination values are a 400 JSON error checked before the device
// lookup; an unregistered device is a 404 JSON error with no listing content.
func TestListSessionsRejectsBadParams(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	createSessions(t, h, "dev-1", "sess-1")

	for _, query := range []string{
		"limit=0", "limit=-1", "limit=1001", "limit=x", "limit=1.5",
		"offset=-1", "offset=x", "offset=1.5",
	} {
		r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/sessions?"+query, nil)
		w := serveRecorder(h, r)
		if w.Code != http.StatusBadRequest {
			t.Fatalf("?%s = %d, want 400 body=%s", query, w.Code, w.Body.String())
		}
		assertJSONError(t, w)
	}

	// Unregistered device: 404 JSON with no listing content.
	r := httptest.NewRequest(http.MethodGet, "/v1/devices/ghost/sessions", nil)
	w := serveRecorder(h, r)
	if w.Code != http.StatusNotFound {
		t.Fatalf("unknown device = %d, want 404", w.Code)
	}
	assertJSONError(t, w)
	if strings.Contains(w.Body.String(), "sess-1") || strings.Contains(w.Body.String(), "sessions") {
		t.Fatalf("404 body leaks listing: %s", w.Body.String())
	}

	// Shape errors win over the device lookup: 400 even for a ghost device.
	r = httptest.NewRequest(http.MethodGet, "/v1/devices/ghost/sessions?limit=0", nil)
	if rec := serveRecorder(h, r); rec.Code != http.StatusBadRequest {
		t.Fatalf("ghost with bad limit = %d, want 400", rec.Code)
	}

	// None of the rejections changed the listing.
	_, ids, _ := listSessions(t, h, "/v1/devices/dev-1/sessions")
	if !equalStrings(ids, []string{"sess-1"}) {
		t.Fatalf("list after rejections = %v", ids)
	}
}

// Empty identifiers, trailing slashes, extra segments and verbs other than
// GET/POST on the collection path are all 400 JSON errors — never a redirect
// or HTML — and change nothing.
func TestListSessionsShapeContract(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	createSessions(t, h, "dev-1", "sess-1")

	cases := []struct {
		name   string
		method string
		path   string
	}{
		{"empty device segment", http.MethodGet, "/v1/devices//sessions"},
		{"trailing slash on collection", http.MethodGet, "/v1/devices/dev-1/sessions/"},
		{"extra segment on get", http.MethodGet, "/v1/devices/dev-1/sessions/sess-1"},
		{"two extra segments on get", http.MethodGet, "/v1/devices/dev-1/sessions/sess-1/extra"},
		{"put on the collection", http.MethodPut, "/v1/devices/dev-1/sessions"},
		{"patch on the collection", http.MethodPatch, "/v1/devices/dev-1/sessions"},
		{"delete short of the session id", http.MethodDelete, "/v1/devices/dev-1/sessions"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			r := httptest.NewRequest(tc.method, tc.path, nil)
			w := serveRecorder(h, r)
			if w.Code != http.StatusBadRequest {
				t.Fatalf("%s %s = %d, want 400", tc.method, tc.path, w.Code)
			}
			assertJSONError(t, w)
			if loc := w.Header().Get("Location"); loc != "" {
				t.Fatalf("malformed request produced a redirect to %q", loc)
			}
		})
	}

	// Zero writes: the listing is unchanged and a GET body is ignored by the
	// read-only route.
	_, ids, _ := listSessions(t, h, "/v1/devices/dev-1/sessions")
	if !equalStrings(ids, []string{"sess-1"}) {
		t.Fatalf("list after rejected shapes = %v", ids)
	}
}

// A GET with an unexpected body still answers the read-only listing and
// creates nothing.
func TestListSessionsIgnoresBody(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev")
	createSessions(t, h, "dev", "sess")

	r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev/sessions", strings.NewReader(`{"sessionId":"ignored"}`))
	r.Header.Set("Content-Type", "application/json")
	w := serveRecorder(h, r)
	if w.Code != http.StatusOK {
		t.Fatalf("GET with body = %d %s", w.Code, w.Body.String())
	}
	_, ids, count := listSessions(t, h, "/v1/devices/dev/sessions")
	if count != 1 || !equalStrings(ids, []string{"sess"}) {
		t.Fatalf("listing changed after a GET: %v", ids)
	}
}

// A deleted session vanishes from the listing; deregistering the device
// removes every session it owns and turns its listing into the same 404 a
// never-registered device gets. Other devices' sessions survive both.
func TestListSessionsReflectsDeleteAndDeregister(t *testing.T) {
	h, _ := newTestHandler(t)
	registerDevice(t, h, "dev-1")
	registerDevice(t, h, "dev-2")
	createSessions(t, h, "dev-1", "sess-a", "sess-b")
	createSessions(t, h, "dev-2", "sess-c")

	// Owner delete removes just that session.
	w, _ := doRequest(t, h, http.MethodDelete, "/v1/devices/dev-1/sessions/sess-a")
	if w.Code != http.StatusOK {
		t.Fatal(w.Body.String())
	}
	_, ids, _ := listSessions(t, h, "/v1/devices/dev-1/sessions")
	if !equalStrings(ids, []string{"sess-b"}) {
		t.Fatalf("list after session delete = %v", ids)
	}

	// Re-creating the deleted id lists it again, sorted by id.
	createSessions(t, h, "dev-1", "sess-a")
	_, ids, _ = listSessions(t, h, "/v1/devices/dev-1/sessions")
	if !equalStrings(ids, []string{"sess-a", "sess-b"}) {
		t.Fatalf("list after recreate = %v", ids)
	}

	// Deregister dev-1: its whole listing is gone (404), and dev-2 is
	// untouched.
	w, _ = doRequest(t, h, http.MethodDelete, "/v1/devices/dev-1")
	if w.Code != http.StatusOK {
		t.Fatal(w.Body.String())
	}
	r := httptest.NewRequest(http.MethodGet, "/v1/devices/dev-1/sessions", nil)
	if rec := serveRecorder(h, r); rec.Code != http.StatusNotFound {
		t.Fatalf("list after deregister = %d, want 404", rec.Code)
	}
	_, ids, _ = listSessions(t, h, "/v1/devices/dev-2/sessions")
	if !equalStrings(ids, []string{"sess-c"}) {
		t.Fatalf("other device after deregister = %v", ids)
	}

	// A re-registered same-named device starts with an empty listing.
	registerDevice(t, h, "dev-1")
	w, ids, count := listSessions(t, h, "/v1/devices/dev-1/sessions")
	if w.Code != http.StatusOK || count != 0 || len(ids) != 0 {
		t.Fatalf("re-registered device list = %d %v count=%d", w.Code, ids, count)
	}
}

// The keyword "sessions" as a device id is an ordinary identifier; the word
// is an endpoint segment only in its fixed position.
func TestListSessionsKeywordAsDeviceID(t *testing.T) {
	h, _ := newTestHandler(t)

	// Unregistered device literally named "sessions": same 404 as any other
	// unregistered id, reached on the ordinary collection route.
	r := httptest.NewRequest(http.MethodGet, "/v1/devices/sessions/sessions", nil)
	w := serveRecorder(h, r)
	if w.Code != http.StatusNotFound {
		t.Fatalf("device id 'sessions' = %d, want 404", w.Code)
	}
	assertJSONError(t, w)

	// Once registered it behaves like every other device: creates and lists.
	registerDevice(t, h, "sessions")
	createSessions(t, h, "sessions", "sess")
	_, ids, count := listSessions(t, h, "/v1/devices/sessions/sessions")
	if count != 1 || !equalStrings(ids, []string{"sess"}) {
		t.Fatalf("device id 'sessions' list = %v count=%d", ids, count)
	}

	// And a session id literally named "sessions" is an ordinary id too.
	createSessions(t, h, "sessions", "sessions")
	_, ids, _ = listSessions(t, h, "/v1/devices/sessions/sessions")
	if !equalStrings(ids, []string{"sess", "sessions"}) {
		t.Fatalf("session id 'sessions' list = %v", ids)
	}
}

// Repeated reads and reads across a process restart return byte-identical
// bodies; the read changes nothing.
func TestListSessionsDeterministicAndDurable(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "sync.db")
	open := func(t *testing.T) (http.Handler, *app.App) {
		t.Helper()
		s, err := app.Open(dbPath)
		if err != nil {
			t.Fatal(err)
		}
		return NewHandler(s), s
	}

	h, s := open(t)
	registerDevice(t, h, "dev")
	createSessions(t, h, "dev", "sess-c", "sess-a", "sess-b")

	snapshot := func() map[string]string {
		bodies := map[string]string{}
		for _, url := range []string{
			"/v1/devices/dev/sessions",
			"/v1/devices/dev/sessions?limit=1&offset=0",
			"/v1/devices/dev/sessions?limit=1&offset=1",
			"/v1/devices/dev/sessions?limit=1&offset=2",
			"/v1/devices/dev/sessions?offset=3",
		} {
			r := httptest.NewRequest(http.MethodGet, url, nil)
			w := serveRecorder(h, r)
			if w.Code != http.StatusOK {
				t.Fatalf("GET %s = %d", url, w.Code)
			}
			bodies[url] = w.Body.String()
		}
		return bodies
	}

	before := snapshot()
	// An immediate repeat is byte-for-byte identical.
	if again := snapshot(); fmt.Sprint(again) != fmt.Sprint(before) {
		t.Fatalf("repeat read changed:\nbefore=%v\nafter=%v", before, again)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

	h, s = open(t)
	defer func() { _ = s.Close() }()
	after := snapshot()
	for url, body := range before {
		if after[url] != body {
			t.Fatalf("GET %s after restart = %q, want %q", url, after[url], body)
		}
	}
}

package events

import (
	"context"
	"database/sql"
	"time"
)

// DocumentExists reports whether documentID is a known document rather than an
// empty namespace: it has any online change row, or a compaction boundary from
// a log that was (fully or partially) trimmed.
func (s *Service) DocumentExists(documentID string) (bool, error) {
	var known bool
	if err := s.db.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_boundaries WHERE document_id = ?)`,
		documentID, documentID,
	).Scan(&known); err != nil {
		return false, err
	}
	return known, nil
}

// ListChanges returns at most limit changes for documentID whose cursor is
// greater than after and still online, in cursor order, together with the
// cursor to pass as the next after value. An unknown document yields an empty
// list and cursor 0; a known document with no rows past after yields
// nextCursor == max(after, boundary), so a caller positioned inside the
// trimmed range resumes from the compaction boundary.
func (s *Service) ListChanges(documentID string, after, limit int64) ([]ListedChange, int64, error) {
	rows, err := s.db.Query(
		`SELECT id, device_id, payload, cursor FROM changes
		 WHERE document_id = ? AND cursor > ?
		 ORDER BY cursor ASC
		 LIMIT ?`,
		documentID, after, limit,
	)
	if err != nil {
		return nil, 0, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	var maxCursor int64 = after
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, 0, err
		}
		out = append(out, c)
		maxCursor = c.Cursor
	}
	if err := rows.Err(); err != nil {
		return nil, 0, err
	}

	// Distinguish an unknown document from a known one with nothing new:
	// unknown documents must report nextCursor 0, while a known document
	// reports the greater of after and the compaction boundary.
	if len(out) == 0 {
		known, err := s.DocumentExists(documentID)
		if err != nil {
			return nil, 0, err
		}
		if !known {
			return out, 0, nil
		}
		boundary, err := boundaryOfTx(s.db, documentID)
		if err != nil {
			return nil, 0, err
		}
		if boundary > maxCursor {
			maxCursor = boundary
		}
	}
	return out, maxCursor, nil
}

// ExportChanges returns every change of documentID whose cursor lies in the
// closed interval [from, to] and is still in the online log, in ascending
// cursor order. When to is nil no upper bound is applied. An unknown document,
// or a range without any online change — including one that lies entirely
// inside the trimmed region — yields an empty list and no error: the export is
// a read that misses like any other. The (document_id, cursor) unique index
// guarantees a cursor appears at most once.
//
// The single SELECT runs as one SQLite statement over the serialized
// connection, so a batch committed concurrently is observed either with all of
// its rows or not at all — never half of it. The read starts no transaction,
// writes nothing and notifies no waiters, so it cannot move a cursor, produce
// a change record or wake a parked poll. Each returned row is the same record
// the paged read emits at that cursor.
func (s *Service) ExportChanges(documentID string, from int64, to *int64) ([]ListedChange, error) {
	var (
		rows *sql.Rows
		err  error
	)
	if to == nil {
		rows, err = s.db.Query(
			`SELECT id, device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND cursor >= ?
			 ORDER BY cursor ASC`,
			documentID, from,
		)
	} else {
		rows, err = s.db.Query(
			`SELECT id, device_id, payload, cursor FROM changes
			 WHERE document_id = ? AND cursor >= ? AND cursor <= ?
			 ORDER BY cursor ASC`,
			documentID, from, *to,
		)
	}
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]ListedChange, 0)
	for rows.Next() {
		var c ListedChange
		if err := rows.Scan(&c.ID, &c.DeviceID, &c.Payload, &c.Cursor); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, nil
}

// WaitForChanges blocks until documentID has a change with cursor greater than
// after, a change is committed while waiting, wait elapses, ctx is canceled
// (the client disconnected) or the service stops. It then returns the current
// page of up to limit changes exactly as ListChanges would, with timedOut=true
// only when the wait deadline expired with no new rows.
//
// Registration precedes the first query: a commit landing between the read and
// the park still notifies a registered channel, so no change is missed.
//
// An unknown document is never parked on: it returns immediately with an empty
// list and nextCursor 0, timedOut=false. Data already past after is likewise
// returned immediately. wait <= 0 is an immediately expired deadline.
func (s *Service) WaitForChanges(ctx context.Context, documentID string, after, limit int64, wait time.Duration) (changes []ListedChange, nextCursor int64, timedOut bool, err error) {
	ch, remove := s.registerWait(documentID)
	defer remove()

	changes, nextCursor, err = s.ListChanges(documentID, after, limit)
	if err != nil || len(changes) > 0 {
		return changes, nextCursor, false, err
	}

	// Empty page: distinguish an unknown document (immediate empty/0, never
	// parked on) from a known document caught up to after.
	known, err := s.DocumentExists(documentID)
	if err != nil || !known {
		return changes, 0, false, err
	}

	// Known document, nothing new: a zero wait is an immediately expired
	// deadline; ListChanges already echoes nextCursor == after.
	if wait <= 0 {
		return changes, nextCursor, true, nil
	}

	timer := time.NewTimer(wait)
	defer timer.Stop()

	select {
	case <-ch:
		// Woken by a committed change, a whole-document deletion, or
		// InterruptWaits. A deleted document is an unknown document now: answer
		// an empty page at cursor 0 with timedOut=false rather than reporting a
		// deadline expiry. Any other empty re-read keeps the old timeout shape.
		s.mu.Lock()
		closing := s.closed
		s.mu.Unlock()
		if closing {
			return nil, 0, false, ErrStoreClosing
		}
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		if err != nil {
			return nil, 0, false, err
		}
		if len(changes) == 0 {
			known, knownErr := s.DocumentExists(documentID)
			if knownErr != nil {
				return nil, 0, false, knownErr
			}
			if !known {
				return changes, 0, false, nil
			}
		}
		return changes, nextCursor, len(changes) == 0, err
	case <-timer.C:
		// Timeout with no new rows: echo the caller's cursor without
		// advancing it. The document was known above, so ListChanges returns
		// nextCursor == after for an empty page.
		changes, nextCursor, err = s.ListChanges(documentID, after, limit)
		return changes, nextCursor, len(changes) == 0, err
	case <-ctx.Done():
		return nil, 0, false, ctx.Err()
	}
}

// registerWait parks a channel for documentID and returns it together with a
// removal function. The channel is closed on the next committed change to the
// document, or when the service stops.
func (s *Service) registerWait(documentID string) (ch chan struct{}, remove func()) {
	ch = make(chan struct{}, 1)

	s.mu.Lock()
	defer s.mu.Unlock()
	if s.closed {
		// Shutdown beat the registration: signal immediately so the caller does
		// not park on a channel nobody will close.
		close(ch)
		return ch, func() {}
	}
	s.nextWait++
	id := s.nextWait
	set := s.waits[documentID]
	if set == nil {
		set = make(map[uint64]chan struct{})
		s.waits[documentID] = set
	}
	set[id] = ch
	return ch, func() {
		s.mu.Lock()
		if set, ok := s.waits[documentID]; ok {
			delete(set, id)
			if len(set) == 0 {
				delete(s.waits, documentID)
			}
		}
		s.mu.Unlock()
	}
}

// notifyWaiters signals every long poll parked on documentID and every
// subscription open on it. It is called only after a change-bearing
// transaction has committed, so parked readers observe the new rows when they
// re-query and pushed frames describe committed changes.
func (s *Service) notifyWaiters(documentID string) {
	s.mu.Lock()
	set := s.waits[documentID]
	delete(s.waits, documentID)
	s.mu.Unlock()
	for _, ch := range set {
		close(ch)
	}
	s.signalSubscribers(documentID)
}

// Package authz is the permission service: the durable, per-document and
// per-device authorization ledger together with the system's single revoke
// verdict.
//
// Every (document, device) pair starts authorized; a grant or revoke is
// recorded per pair. The lookup and the write run in one serialized
// transaction on the shared connection and commit to disk, so concurrent
// grant/revoke calls each land as a complete state and survive a restart.
//
// The other services do not read the permission table. They take their
// registration-and-authorization verdict through AuthorizedTx, evaluated
// inside their own write transaction, so a rejected request is judged before
// any document content is observed and the gate and the gated work commit as
// one judgment. Revoking never deletes changes, snapshots, sessions or CRDT
// state; it only produces the denial and, after the revoke commits, notifies
// the registered revoke sinks (the live subscription registries) so they can
// end the affected connections with the one-time, sticky 4403 close.
package authz

import (
	"database/sql"
	"errors"
	"sync"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// schema is created when the service is constructed; its shape is unchanged
// from the pre-refactor layout, so authorization rows already on disk stay
// readable.
const schema = `
CREATE TABLE IF NOT EXISTS document_permissions (
	document_id TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	authorized  INTEGER NOT NULL,
	PRIMARY KEY (document_id, device_id)
);
`

// RevokeSink observes a committed revoke. The change event service and the
// CRDT service register themselves to end the affected live subscriptions; a
// sink must not block and must be safe to call after the revoke transaction
// has committed. The permission service depends on this interface alone, so
// the dependency points from the observers toward the verdict and never back.
type RevokeSink interface {
	PermissionRevoked(documentID, deviceID string)
}

// Service is the permission service.
type Service struct {
	db *sql.DB

	mu    sync.Mutex
	sinks []RevokeSink
}

// New constructs the permission service over the shared kernel handle and
// creates its table.
func New(kernel *store.Store) (*Service, error) {
	db := kernel.DB()
	if _, err := db.Exec(schema); err != nil {
		return nil, err
	}
	return &Service{db: db}, nil
}

// AddRevokeSink registers an observer notified after every committed revoke.
// It is called by the composition root while wiring the services, before the
// surface serves requests.
func (s *Service) AddRevokeSink(sink RevokeSink) {
	s.mu.Lock()
	s.sinks = append(s.sinks, sink)
	s.mu.Unlock()
}

// AuthorizedTx is the shared gate: it returns nil when deviceID is registered
// and currently authorized for documentID, store.ErrDeviceNotFound when the
// device is not registered and store.ErrPermissionDenied when its access has
// been revoked. It runs inside the caller's transaction q, so the verdict is
// taken on the same serialized connection as the work it guards, before any
// document content is read.
func (s *Service) AuthorizedTx(q store.DBTX, documentID, deviceID string) error {
	exists, err := store.DeviceExistsTx(q, deviceID)
	if err != nil {
		return err
	}
	if !exists {
		return store.ErrDeviceNotFound
	}
	var stored int
	err = q.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No deviation row: devices start authorized.
		return nil
	case err != nil:
		return err
	default:
		if stored == 0 {
			return store.ErrPermissionDenied
		}
		return nil
	}
}

// DeviceAuthorizedTx adapts the shared gate to the change event and CRDT
// services' Gate interface (which names *sql.Tx). The verdict is identical.
func (s *Service) DeviceAuthorizedTx(tx *sql.Tx, documentID, deviceID string) error {
	return s.AuthorizedTx(tx, documentID, deviceID)
}

// SetDocumentPermission grants or revokes deviceID's access to documentID and
// reports whether the stored permission actually changed.
//
// Every device starts authorized for every document, so the first revoke is
// the first write for the pair (changed=true); repeating a state that already
// holds writes nothing and reports changed=false. An unregistered device
// yields store.ErrDeviceNotFound and nothing is written. The lookup and the
// write run in one serialized transaction, so concurrent grant/revoke calls
// each commit completely and the final state matches the last committed
// action. After a revoke commits, every registered sink is notified; a grant
// notifies nothing (a prior revoke already ended the connection stickily).
func (s *Service) SetDocumentPermission(documentID, deviceID string, authorized bool) (changed bool, err error) {
	tx, err := s.db.Begin()
	if err != nil {
		return false, err
	}
	defer func() { _ = tx.Rollback() }()

	exists, err := store.DeviceExistsTx(tx, deviceID)
	if err != nil {
		return false, err
	}
	if !exists {
		return false, store.ErrDeviceNotFound
	}

	current := true // devices start authorized; a row only records a deviation
	var stored int
	err = tx.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// No row: the default (authorized) holds.
	case err != nil:
		return false, err
	default:
		current = stored != 0
	}
	if current == authorized {
		return false, tx.Commit()
	}

	v := 0
	if authorized {
		v = 1
	}
	if _, err := tx.Exec(
		`INSERT INTO document_permissions (document_id, device_id, authorized) VALUES (?, ?, ?)
		 ON CONFLICT (document_id, device_id) DO UPDATE SET authorized = excluded.authorized`,
		documentID, deviceID, v,
	); err != nil {
		return false, err
	}
	if err := tx.Commit(); err != nil {
		return false, err
	}

	// A grant cannot unblock a subscription (the first revoke already ended
	// it, stickily); only a revoke needs to end live subscriptions.
	if !authorized {
		s.mu.Lock()
		sinks := append([]RevokeSink(nil), s.sinks...)
		s.mu.Unlock()
		for _, sink := range sinks {
			sink.PermissionRevoked(documentID, deviceID)
		}
	}
	return true, nil
}

// DeleteDevicePermissionsTx removes every document-permission ledger row that
// names deviceID, inside the caller's transaction: grants and revokes the
// deregistered device held on documents vanish together with the device. It is
// the permission service's share of device deregistration, run in the same
// serialized transaction as the registration layer's cascade, so the row
// removals and the device deletion commit as one judgment. After the device
// row is gone the default verdict would be "unregistered" anyway; clearing the
// rows guarantees a device that later re-registers the same id starts with no
// inherited authorization state.
func (s *Service) DeleteDevicePermissionsTx(q store.DBTX, deviceID string) error {
	_, err := q.Exec(
		`DELETE FROM document_permissions WHERE device_id = ?`, deviceID,
	)
	return err
}

// DocumentHasRowsTx reports whether the ledger holds any row (a grant or a
// revoke deviation) for documentID. It is part of document existence: a
// document whose only durable trace is a permission deviation still exists and
// can be deleted so that the same id is later a brand-new document with no
// inherited authorization state.
func (s *Service) DocumentHasRowsTx(q store.DBTX, documentID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM document_permissions WHERE document_id = ?)`,
		documentID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// DeleteDocumentPermissionsTx removes every permission-ledger row that names
// documentID, inside the caller's transaction: the per-device grant/revoke
// deviations of a deleted document vanish with it, so when the same id is
// created again every pair starts from the default (authorized) with no
// inherited ledger state. It is the permission service's share of document
// deletion, run in the same serialized transaction as the change-event and
// CRDT cascades, so the row removals and the document deletion commit as one
// judgment.
func (s *Service) DeleteDocumentPermissionsTx(q store.DBTX, documentID string) error {
	_, err := q.Exec(
		`DELETE FROM document_permissions WHERE document_id = ?`, documentID,
	)
	return err
}

// DocumentAuthorized reports whether deviceID currently holds permission for
// documentID. Devices start authorized, so an absent row means authorized.
func (s *Service) DocumentAuthorized(documentID, deviceID string) (bool, error) {
	var stored int
	err := s.db.QueryRow(
		`SELECT authorized FROM document_permissions WHERE document_id = ? AND device_id = ?`,
		documentID, deviceID,
	).Scan(&stored)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return true, nil
	case err != nil:
		return false, err
	default:
		return stored != 0, nil
	}
}

// PermissionEntry is one row of a document's permission ledger: a currently
// registered device id together with its authorization for the document.
type PermissionEntry struct {
	DeviceID   string
	Authorized bool
}

// ListDocumentPermissions is the read-only ledger view of one document: one
// entry per currently registered device, in ascending lexicographic device-id
// order, paged by limit/offset against that same order.
//
// A device with no ledger row starts authorized, so its entry reports
// Authorized=true; a device whose latest committed action was a revoke reports
// false. Deregistered devices carry no device row and their ledger rows were
// removed by the deregistration cascade, so they never appear. An unknown
// document is indistinguishable from one on which every device keeps the
// default: every registered device lists authorized. The read runs in one
// serialized transaction, creates no row, moves no cursor and notifies no sink.
func (s *Service) ListDocumentPermissions(documentID string, limit, offset int64) ([]PermissionEntry, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	rows, err := tx.Query(
		`SELECT d.id, COALESCE(p.authorized, 1) AS authorized
		 FROM devices d
		 LEFT JOIN document_permissions p
		   ON p.document_id = ? AND p.device_id = d.id
		 ORDER BY d.id ASC
		 LIMIT ? OFFSET ?`,
		documentID, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	entries := make([]PermissionEntry, 0)
	for rows.Next() {
		var entry PermissionEntry
		var stored int
		if err := rows.Scan(&entry.DeviceID, &stored); err != nil {
			return nil, err
		}
		entry.Authorized = stored != 0
		entries = append(entries, entry)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return entries, tx.Commit()
}

// Document-level deletion removes every durable row a document owns in the
// change event service: the online change log, the compaction boundary, the
// retained idempotency summaries of trimmed changes, snapshots and restore
// provenance. After the deletion the same document id is a brand-new document:
// an unknown document reads as an empty list at cursor 0, and the next commit
// allocates cursor 1 again, because every row — the boundary included — that
// remembered the old cursor space is gone.
//
// The work runs inside the caller's serialized transaction, sharing it with the
// CRDT state and permission-ledger deletions of the same operation, so a
// document deletion either removes every row or none; a document with no row
// in any of the services misses (ErrDocumentNotFound) and writes nothing.

package events

import (
	"errors"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// ErrDocumentNotFound reports that a delete targets a document id that has no
// durable data anywhere — it was never created or was already deleted. The
// caller maps it to 404; nothing is written.
var ErrDocumentNotFound = errors.New("document not found")

// DocumentDataExistsTx reports whether the change event service holds any row
// for documentID: an online change, a compaction boundary, a retained
// trimmed-id summary, a snapshot, a snapshot version marker or a restore
// record. It runs inside the caller's transaction so the existence verdict is
// one judgment with the deletion that follows it.
func (s *Service) DocumentDataExistsTx(q store.DBTX, documentID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_boundaries WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_identities WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM snapshots WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM snapshot_versions WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM restores WHERE document_id = ?)`,
		documentID, documentID, documentID, documentID, documentID, documentID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// DeleteDocumentDataTx removes every change-event row of documentID inside the
// caller's serialized transaction: the online log and restore records first
// (the rows that reference cursors), then snapshots and their named version
// markers, the retained idempotency summaries and finally the compaction
// boundary. With the boundary gone the cursor space restarts from 1 when the
// id is created again, and with the markers gone a re-created document of the
// same name inherits no version. It does not judge existence — the caller
// checks DocumentDataExistsTx (and the CRDT service's equivalent) once before
// deleting — so it never returns ErrDocumentNotFound on its own.
func (s *Service) DeleteDocumentDataTx(q store.DBTX, documentID string) error {
	stmts := []string{
		`DELETE FROM restores WHERE document_id = ?`,
		`DELETE FROM changes WHERE document_id = ?`,
		`DELETE FROM snapshot_versions WHERE document_id = ?`,
		`DELETE FROM snapshots WHERE document_id = ?`,
		`DELETE FROM change_identities WHERE document_id = ?`,
		`DELETE FROM change_boundaries WHERE document_id = ?`,
	}
	for _, stmt := range stmts {
		if _, err := q.Exec(stmt, documentID); err != nil {
			return err
		}
	}
	return nil
}

