// Read-only listing of the documents a device's sessions have written changes
// into. It is the change-event service's share of the device-scoped document
//清单: one distinct document id per document that still carries an online
// change stamped with the device, in ascending lexicographic document-id
// order, paged by limit/offset over that fixed order.

package events

// ListDeviceDocuments returns the distinct document ids that carry an online
// change whose originating device is deviceID, each at most once, sorted by
// document id in ascending lexicographic order and paged by limit/offset as a
// slice over that fixed order — so with no intervening commit or delete,
// successive pages neither repeat nor skip an id, and an offset past the end
// yields an empty (non-nil) slice and no error.
//
// Only the online change log is consulted: a document whose changes were all
// moved out by compaction leaves the listing even though the retained
// idempotency summaries remain (its "changes have been cleared"), and a
// whole-document deletion removes every row it could be derived from. The
// caller separately decides whether the device currently exists and whether
// it still owns a live session — those tables belong to the registration
// layer — so this method reports the change-attribution set alone. The read
// starts no write transaction, writes nothing, allocates no cursor and
// notifies no waiter or subscriber; its body is stable across repeated reads
// and process restarts while the committed log is unchanged.
func (s *Service) ListDeviceDocuments(deviceID string, limit, offset int64) ([]string, error) {
	rows, err := s.db.Query(
		`SELECT DISTINCT document_id FROM changes
		 WHERE device_id = ?
		 ORDER BY document_id ASC
		 LIMIT ? OFFSET ?`,
		deviceID, limit, offset,
	)
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	ids := make([]string, 0)
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		ids = append(ids, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return ids, nil
}

